<script setup lang="ts">
import { computed, watch } from 'vue';
import { state as stateSource, mode } from '../workbench/store';
import { route as routeSource, go, setQuery } from '../workbench/navigation';
import { sessions, loadSessions, loading, liveError, unreadable } from '../workbench/live';
import { reviewTraces, traceStatus, downloadTrace } from '../workbench/traces';
import PagingBar from './PagingBar.vue';
const route=routeSource,state=stateSource;
watch(()=>mode.value,v=>{if(v==='real')void loadSessions();},{immediate:true});
const students=computed(()=>[...new Map(state.spaces.map(s=>[s.studentId,{id:s.studentId,name:s.studentName}])).values()]);
const spaces=computed(()=>state.spaces.filter(s=>!route.student||s.studentId===route.student));
const rows=computed(()=>mode.value==='demo'?state.activities.map(a=>{const ls=state.spaces.find(s=>s.id===a.ls),tr=reviewTraces[a.id];return {id:a.id,title:a.name,at:a.at,studentId:ls?.studentId||'',student:ls?.studentName||'未记录',ls:a.ls,scope:ls?.name||a.ls,chapter:ls?.chapters.map(id=>state.objects.find(o=>o.id===id&&o.version===a.versions[id])?.name||id).join('、')||'未记录',status:tr?.status||'unknown',duration:tr?.duration||null};}):sessions.value.map(s=>({id:s.id,title:s.title,at:s.updatedAt,studentId:'',student:'未绑定正式学生',ls:s.scope.space,scope:s.scope.label,chapter:'未绑定正式章节',status:s.error?'error':s.pending?'pending':s.phase==='ended'?'ended':'saved',duration:null})));
function dateOnly(at:string){const d=new Date(at);return Number.isNaN(d.getTime())?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const dateError=computed(()=>route.range==='custom'&&route.since&&route.until&&route.since>route.until?'开始日期不能晚于结束日期。':'');
function inRange(at:string){if(!route.range||route.range==='all')return true;const date=dateOnly(at);if(!date||dateError.value)return false;if(route.range==='custom')return (!route.since||date>=route.since)&&(!route.until||date<=route.until);const end=new Date(),start=new Date(end);start.setDate(start.getDate()-(route.range==='7days'?6:route.range==='30days'?29:0));return date>=dateOnly(start.toISOString())&&date<=dateOnly(end.toISOString());}
const filtered=computed(()=>rows.value.filter(r=>(!route.q||`${r.title} ${r.id} ${r.student} ${r.scope}`.toLowerCase().includes(route.q.toLowerCase()))&&(!route.student||r.studentId===route.student)&&(!route.filter||r.ls===route.filter)&&(!route.status||r.status===route.status)&&inRange(r.at)));
const page=computed(()=>Math.min(route.p,Math.max(1,Math.ceil(filtered.value.length/10))));
const stats=computed(()=>{const list=filtered.value,timed=list.filter(r=>r.duration!==null);return {total:list.length,students:new Set(list.filter(r=>r.studentId).map(r=>r.studentId)).size,spaces:new Set(list.map(r=>r.ls)).size,normal:list.filter(r=>r.status==='normal').length,partial:list.filter(r=>r.status==='partial').length,idle:list.filter(r=>r.status==='idle').length,mean:timed.length?(timed.reduce((sum,r)=>sum+r.duration!,0)/timed.length/1000).toFixed(1):null,timed:timed.length};});
const statusOptions=computed(()=>mode.value==='demo'?['normal','partial','idle','unknown']:['saved','pending','error','ended']);
const scopeOptions=computed(()=>mode.value==='demo'?spaces.value.map(s=>({id:s.id,label:`${s.studentName} · ${s.name}`})):[...new Map(sessions.value.map(s=>[s.scope.space,{id:s.scope.space,label:s.scope.label}])).values()]);
function open(id:string){go('activity',{id,scope:mode.value==='demo'?id:'',returnTo:location.hash});}
function reset(){setQuery({q:'',student:'',filter:'',status:'',range:'all',since:'',until:'',p:1});}
</script>
<template><div class="wb-page trace-list"><header class="page-header"><div><h2>交互审查</h2><p class="page-desc">{{mode==='demo'?'选择一次交互，检查输入、处理步骤、输出与评价依据。':'查看本机已保存的会话；当前尚无正式学生身份与逐阶段处理日志。'}}</p></div><div class="button-row"><button v-if="mode==='real'" class="btn" :disabled="loading" @click="loadSessions">刷新真实会话</button><button class="btn" :disabled="loading||!!liveError&&mode==='real'" @click="downloadTrace('interaction-index.json',{source:mode,filters:{q:route.q,student:route.student,space:route.filter,status:route.status,range:route.range,since:route.since,until:route.until},notice:mode==='demo'?'人工编写示例，时长包含等待，不能用于真实性能统计':'只导出当前已读取的会话索引，不包含未记录的 Trace',items:filtered})">导出筛选结果 JSON</button></div></header>
  <div class="stats-grid" data-testid="trace-stats"><div class="stat-card primary"><span>{{mode==='demo'?'示例交互数':'已读取会话数'}}</span><strong>{{stats.total}}</strong><small>{{mode==='demo'?`${stats.students} 名示例学生 · ${stats.spaces} 个学习空间`:'正式学生与学习空间身份未接入'}}</small></div><template v-if="mode==='demo'"><div class="stat-card"><span>处理完成</span><strong>{{stats.normal}}</strong><small>不代表学习目标达标</small></div><div class="stat-card"><span>待复核</span><strong>{{stats.partial}}</strong><small>含故意错误的示例解释</small></div><div class="stat-card"><span>尚无评价</span><strong>{{stats.idle}}</strong><small>不能据此判为失败</small></div><div class="stat-card"><span>平均示例活动时长</span><strong>{{stats.mean===null?'—':stats.mean+'s'}}</strong><small>{{stats.timed}} 条有时长；含作答等待</small></div></template><template v-else><div class="stat-card"><span>有错误记录</span><strong>{{filtered.filter(r=>r.status==='error').length}}</strong><small>按会话当前错误字段</small></div><div class="stat-card"><span>待收束</span><strong>{{filtered.filter(r=>r.status==='pending').length}}</strong><small>查阅不会执行恢复</small></div><div class="stat-card"><span>平均处理耗时</span><strong>—</strong><small>会话索引未记录，不从时间差推算</small></div></template></div>
  <p class="muted stats-note">统计随筛选更新。{{mode==='demo'?'示例时间不是性能测量；步骤未记录的活动不推断状态。':'会话数不等于交互轮数；完整性以成功读取的本机索引为限。'}}</p>
  <div class="toolbar"><label>搜索<input :value="route.q" @input="setQuery({q:($event.target as HTMLInputElement).value,p:1})" placeholder="学生、活动、会话编号或内容"/></label><label>学生<select :value="route.student" :disabled="mode==='real'" @change="setQuery({student:($event.target as HTMLSelectElement).value,filter:'',p:1})"><option value="">{{mode==='demo'?'全部学生':'未绑定正式学生'}}</option><option v-for="s in mode==='demo'?students:[]" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>学习空间<select :value="route.filter" @change="setQuery({filter:($event.target as HTMLSelectElement).value,p:1})"><option value="">{{mode==='demo'?'全部空间':'全部会话课程范围'}}</option><option v-for="s in scopeOptions" :key="s.id" :value="s.id">{{s.label}}</option></select></label><label>处理状态<select :value="route.status" @change="setQuery({status:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部状态</option><option v-for="s in statusOptions" :key="s" :value="s">{{traceStatus[s]}}</option></select></label><label>时间段<select :value="route.range||'all'" @change="setQuery({range:($event.target as HTMLSelectElement).value,p:1})"><option value="all">全部时间</option><option value="today">今天</option><option value="7days">最近 7 天</option><option value="30days">最近 30 天</option><option value="custom">自定义日期</option></select></label><template v-if="route.range==='custom'"><label>开始日期<input type="date" :value="route.since" @input="setQuery({since:($event.target as HTMLInputElement).value,p:1})"/></label><label>结束日期<input type="date" :value="route.until" @input="setQuery({until:($event.target as HTMLInputElement).value,p:1})"/></label></template><button class="btn" @click="reset">清除筛选</button></div>
  <p v-if="dateError" class="callout danger" role="alert">{{dateError}}</p><p class="muted stats-note">日期按本机时区的自然日筛选；示例采用活动开始时间，真实会话采用最后更新时间。</p>
  <p v-if="mode==='real'&&liveError" class="callout danger">{{liveError}}。无法读取不代表没有会话；已有索引可能过时。</p><p v-if="mode==='real'&&loading" role="status">正在读取真实会话索引…</p><div v-if="mode==='real'&&unreadable.length" class="callout amber"><strong>{{unreadable.length}} 个会话文件无法解析，未计入统计</strong><p v-for="e in unreadable" :key="e.id">{{e.id}}：{{e.reason}}</p></div>
  <section class="table-card"><table class="data-table"><thead><tr><th>{{mode==='demo'?'开始时间':'最后更新'}}</th><th>学生</th><th>{{mode==='demo'?'学习空间／章节':'课程范围'}}</th><th>交互摘要</th><th>时长</th><th>状态</th></tr></thead><tbody><tr v-for="r in filtered.slice((page-1)*10,page*10)" :key="r.id"><td>{{r.at}}</td><td>{{r.student}}</td><td>{{r.scope}}<small>{{r.chapter}}</small></td><td><button class="text-link" @click="open(r.id)">{{r.title}}</button><small>{{r.id}}</small></td><td>{{r.duration===null?'—':(r.duration/1000).toFixed(1)+'s'}}</td><td><span class="status-tag" :class="r.status">{{traceStatus[r.status]}}</span></td></tr></tbody></table><p v-if="!filtered.length&&!loading&&!(liveError&&mode==='real')" class="empty">没有符合条件的记录。</p></section><PagingBar :total="filtered.length" :page="page"/>
</div></template>
<style scoped>
.stats-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.stat-card{display:flex;flex-direction:column;gap:6px;background:white;border:1px solid #e1e8ed;border-radius:10px;padding:14px 16px}.stat-card.primary{border-left:3px solid #2d6a4f}.stat-card>span{font-size:12px;color:#697c8a}.stat-card strong{font-size:24px;color:#1a3a2e}.stat-card small{font-size:11px;color:#5a7a6a}.stats-note{font-size:12px}.trace-list .toolbar{align-items:flex-end}.trace-list .toolbar label{min-width:140px;flex:1}.trace-list .table-card{overflow-x:auto}.data-table{min-width:760px}.data-table td{font-size:12px;overflow-wrap:anywhere;max-width:260px}.status-tag{white-space:nowrap;border-radius:8px;padding:4px 8px;background:#edf1f5;font-size:11px}.status-tag.normal,.status-tag.saved{background:#e8f5ee;color:#2d8a5e}.status-tag.partial,.status-tag.pending{background:#fef5e0;color:#946c1c}.status-tag.error{background:#fdf0ed;color:#b85c3c}@media(max-width:1200px){.stats-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
</style>
